function validate([positions]) {
  if (!Array.isArray(positions) || positions.length < 1 || positions.length > 1000) return 'positions needs 1 to 1000 squares.';
  for (const p of positions) {
    if (!Array.isArray(p) || p.length !== 2 || !p.every(Number.isInteger)) return 'Each square is a pair [left, sideLength] of integers.';
    if (p[0] < 1 || p[0] > 1e8) return 'Each left edge is between 1 and 10^8.';
    if (p[1] < 1 || p[1] > 1e6) return 'Each side length is between 1 and 10^6.';
  }
  return null;
}

