function fallingSquares(positions) {
  const edges = new Set();
  for (const [left, side] of positions) {
    edges.add(left);
    edges.add(left + side);
  }
  const coords = [...edges].sort((a, b) => a - b);
  const slot = new Map(coords.map((x, i) => [x, i]));
  const n = coords.length;
  const tree = new Array(4 * n).fill(0);
  const pending = new Array(4 * n).fill(0);

  const pushDown = (node) => {
    if (pending[node] > 0) {
      for (const child of [2 * node, 2 * node + 1]) {
        tree[child] = pending[node];
        pending[child] = pending[node];
      }
      pending[node] = 0;
    }
  };

  const query = (node, lo, hi, from, to) => {
    if (to < lo || hi < from) return 0;
    if (from <= lo && hi <= to) return tree[node];
    pushDown(node);
    const mid = (lo + hi) >> 1;
    return Math.max(query(2 * node, lo, mid, from, to), query(2 * node + 1, mid + 1, hi, from, to));
  };

  const assign = (node, lo, hi, from, to, value) => {
    if (to < lo || hi < from) return;
    if (from <= lo && hi <= to) {
      tree[node] = value;
      pending[node] = value;
      return;
    }
    pushDown(node);
    const mid = (lo + hi) >> 1;
    assign(2 * node, lo, mid, from, to, value);
    assign(2 * node + 1, mid + 1, hi, from, to, value);
    tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
  };

  const ans = [];
  let tallest = 0;
  for (const [left, side] of positions) {
    const from = slot.get(left);
    const to = slot.get(left + side) - 1;
    const height = query(1, 0, n - 1, from, to) + side;
    assign(1, 0, n - 1, from, to, height);
    tallest = Math.max(tallest, height);
    ans.push(tallest);
  }
  return ans;
}

