function fallingSquares(positions) {
  const tops = [];
  const result = [];
  let highest = 0;
  for (let i = 0; i < positions.length; i++) {
    const [a, s] = positions[i];
    let base = 0;
    // Rest on the highest earlier square whose span overlaps this one by a positive length.
    for (let j = 0; j < i; j++) {
      const [b, t] = positions[j];
      if (a < b + t && b < a + s) base = Math.max(base, tops[j]);
    }
    tops.push(base + s);
    highest = Math.max(highest, base + s);
    result.push(highest);
  }
  return result;
}

