function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 8);
    const span = 2 + Math.floor(rand() * 12);
    return [Array.from({ length: n }, () => [1 + Math.floor(rand() * span), 1 + Math.floor(rand() * 5)])];
  }
  const n = 1000;
  const span = [5000, 1000000, 100000000][Math.floor(rand() * 3)];
  const maxSide = [100, 1000000][Math.floor(rand() * 2)];
  return [Array.from({ length: n }, () => [1 + Math.floor(rand() * span), 1 + Math.floor(rand() * maxSide)])];
}
